"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[481],{5481:(e,t,o)=>{o.d(t,{Ol:()=>i});let n=JSON.parse('{"M":{"accounts_ui":{"value":true,"owner":"R2","added":"2026-09-05","removeBy":"2026-12-31","why":"ON since 2026-09-22, the day the reader database was stood up and sign-up went live. Sign-in, sign-up and the account section of the profile page. Until 2026-09-25 this switch was wired to nothing: the panel decided on its own whether a service was configured, so turning the switch off changed nothing a reader could see. It is now a real kill-switch read by app/profile/AccountPanel.tsx, and both conditions are required - the switch on AND a service configured. Setting this back to false and rebuilding takes sign-in and sign-up off the site without touching the keys, and the page falls back to the same untouched section that predates the feature. That is the first move in any accounts incident."},"paywall":{"value":false,"owner":"R2","added":"2026-09-05","removeBy":"2026-12-31","why":"Entitlement gating of the paid depth registers, the trial, the lapse state and the subscribe sheet. Plan \xa74. Nothing exists behind this yet."},"push":{"value":false,"owner":"R2","added":"2026-09-05","removeBy":"2026-12-31","why":"Edition push notifications from the native shell. Plan \xa72.2. Hard-blocked on the Apple Developer enrolment (D-iOS-7)."},"region_capture":{"value":false,"owner":"R2","added":"2026-09-05","removeBy":"2026-12-31","why":"Attaching a DOM path, bounding box and screenshot crop to a reader\'s report. Framework section 10 (super-user reports only). Off until the reports table exists and the privacy copy is written."},"principles_page":{"value":false,"owner":"Pigeon","added":"2026-09-05","removeBy":"2026-12-31","why":"A public /principles route stating the editorial standard. docs/PRINCIPLES.md exists; the route does not. Flagged so the route can ship dark and be reviewed before readers see it."},"triage_autoreply":{"value":false,"owner":"Pigeon","added":"2026-09-05","removeBy":"2026-12-31","why":"Answering by-design complaints automatically from the Promise Register. Plan \xa77.6 gates this on measured precision; it must never turn on before that measurement exists."},"event_bundle_writer":{"value":true,"owner":"Pigeon","added":"2026-09-15","removeBy":"2026-12-31","why":"ON since 2026-09-20, with the cost approved. One story written from every outlet and listening channel on an event, not from one article. Measured before switching on: half of the top forty stories had nothing the writer could read, and turning this on with the on-demand article fetch brings that from 22 of 40 down to 14. The blend refuses any sentence whose number, name or quote is not in a cited source, and a refused story falls back to the one-article account. Estimated spend 18 to 33 dollars a month at two prints a day (npm run event-bundle:cost); the real figure is lower because only the researched stories are written at all. Setting this back to false is the first move in any incident: with it off the prompts and cache keys are the ones from before this existed."},"pattern_context":{"value":true,"owner":"Pigeon","added":"2026-09-17","removeBy":"2026-12-31","why":"ON since 2026-09-17, with the cost approved. Each written account is handed a short list of the other stories of the same kind we hold, printed or not, and may summarise them in facts only, never in judgement words. Measured before switching on: 95 percent of the listed stories are truly of the same kind, 6 percent of written accounts get a list at all, and the added spend is about 4 dollars a month at two prints a day (npm run pattern-context:cost). Setting this back to false is the first move in any incident: with no list the writer\'s prompts and cache keys are byte-identical to the build before this existed, which tests/pattern-context.test.mjs asserts."},"event_bundle_join":{"value":true,"owner":"Pigeon","added":"2026-09-15","removeBy":"2026-12-31","why":"ON since 2026-09-20. A listening-channel story about an event we already carry joins that event instead of printing as a second story. Free. It moves the trending tag onto the outlet story, which is the behaviour to watch on the first print after switching it on."},"r417_order":{"value":true,"owner":"Pigeon","added":"2026-09-20","removeBy":"2026-12-31","why":"The whole order of the paper: judge at the door, rank, research only the stories that will be seen, then write, and give everything else our own headline and nothing more. ON in production since 2026-09-21 04:49 UTC through the repo variable PIGEON_FLAGS, which overrides this file; this file read OFF until 2026-10-15 and was corrected to match what actually prints. With it off the ingest is byte for byte what it was: every story is written up as before, and the research and headline steps do not run. Setting it back to false here does NOT turn it off while PIGEON_FLAGS names it: in an incident, remove it from PIGEON_FLAGS first."},"own_headline_gate":{"value":false,"owner":"Pigeon","added":"2026-10-15","removeBy":"2026-12-31","why":"The front-page check for the rule that nothing a reader sees is another outlet\'s words. A story whose printed headline is still the outlet\'s own title is rewritten once more by the repair writer, and taken off the front page if that fails. OFF until Pigeon reads one print with it: on a day the repair writer cannot run, every such story leaves the front page, the lead included. Free to check; each repair is one paid call. Kept OFF by the owner\'s ruling of 2026-10-15; the owner will review it after a week of prints from 2026-10-15."},"dedup.page_pairs":{"value":false,"owner":"Pigeon","added":"2026-10-27","removeBy":"2026-12-31","why":"The page-level repeat check (lib/stories/page-pairs.ts): two rows on the page that tell the same event in near-identical headlines, with a shared place or person, fold into one, the lower row into the higher. It never joins rows of two different stories or rows the same-event judge read as different events. OFF until its controls pass on every replay day; the coverage proof counts the repeats it would fold either way. Free: no model is called."},"go_and_look":{"value":false,"owner":"Pigeon","added":"2026-10-22","removeBy":"2026-12-31","why":"The step that searches Bing\'s free news feed for ANOTHER outlet\'s report of a story whose own outlet blocks us or that we only read by feed, so the Constitutional writer has an article to write from. Built in September, but it never ran on the paper: the publish passed no search. Measured live 2026-10-22: a readable copy for 8 of 48 blocked stories. OFF until the owner rules on using Bing\'s news feed for a commercial paper; no legal review of Microsoft\'s terms is on file. Costs nothing."},"must_run":{"value":true,"owner":"Pigeon","added":"2026-10-22","removeBy":"2026-12-31","why":"The top-of-page rule: a story carried by four or more distinct outlets (items the front-door filter refused count too) must run. This one switch is read by every place that rule changes the page. ON from the day it was added because the story layer only marks stories and nothing reads the mark until the ranking work lands; with it off no story carries the mark and the page is exactly what it was. This is the first move in any incident: set it to false here and republish (PIGEON_FLAGS can only turn a switch on, never off)."},"page_overflow":{"value":false,"owner":"Pigeon","added":"2026-10-30","removeBy":"2026-12-31","why":"Off = the front page stops at 45 rows even on a day with more 4+ outlet stories than that; the lowest-scored of those keep only their own story pages and search. On = every 4+ outlet story stays on the front page however long it gets (the page reached 92 rows on 2026-10-30). Off is the default chosen while the owner decides."},"page_tier":{"value":true,"owner":"Pigeon","added":"2026-10-30","removeBy":"2026-12-31","why":"On = the tiered front page. Every story carried by four or more outlets makes the page. The top 45 by score get the full treatment (context, Constitutional Analysis, vocabulary); every other 4+ outlet story runs below them in an Also today section as one short, sourced, facts-only line. When money is tight the number of full-treatment stories goes down, never the checks. Off = the front page stops at 45 rows, as before (the lowest-scored 4+ outlet stories keep only their own story pages and search)."},"feedback_autofix":{"value":true,"owner":"Pigeon","added":"2026-10-22","removeBy":"2026-12-31","why":"The kill switch for automatic fixes of reader reports. ON: when a reader\'s report names a checkable claim (a duplicate story, a wrong fact, a typo, a broken link, a missing story) and the check PROVES it and the fix fits our rulings, the fix is applied and logged on the desk dashboard (scripts/feedback/worker.mjs, run every 10 minutes by triage-reports.yml). Billing, legal, security and Constitutional claims are never fixed, with this on or off. OFF: reports are still sorted and checked and the findings logged, but nothing is changed, and no republish is started. Setting it to false here (or removing it from PIGEON_FLAGS) is the first move in any incident with the fixer."},"statement_gate":{"value":true,"owner":"Pigeon","added":"2026-10-22","removeBy":"2026-12-31","why":"The front-door filter\'s statement class: a named person with a role in the story, speaking on the record, is reported as a fact instead of refused. OFF until the filter prompt that reads this switch is merged and its first live check passes. After the first live check, scripts/gate/statement-gate-check.mjs turns it off by itself, and logs why on the desk, if fewer than 7 of the 8 saved statements are let in or if any of the 10 saved opinion columns is let in."},"vocab_light_pass":{"value":false,"owner":"Pigeon","added":"2026-10-27","removeBy":"2026-12-31","why":"OFF until a replay proves it. When on, after the fact checks, a page story whose own writing shows fewer than two vocabulary words may get one to three same-meaning single-word swaps to a vocabulary word; numbers, names, negation, hedges and attribution are never touched, a second check must agree the meaning is unchanged, and the original stays on any doubt. At most 25 cents a print. Turning it off restores the text exactly as written."},"editorial_fact_only":{"value":false,"owner":"Pigeon","added":"2026-10-28","removeBy":"2026-12-31","why":"The fact-only line check: nothing we write may praise, blame, give a verdict or give advice in our own voice. When on, a headline, summary or trending write-up carrying such a word is refused and the writer is asked again; a saved line has the word taken out or is not served; the research notes in every section (not only the Constitution note) refuse a sentence that rules in our voice; the ingest sweep mends or removes such a line on every story; and the front-page check holds a story whose shown headline still fails (a story four or more outlets carry prints the plain template line instead). OFF until one print has been read with it on. With it off every one of those paths is byte for byte what it was before the check existed. Free: no model is called by the check itself; a refused line costs one more writer call."}}}');var r=o(5704);let a=n.M;Object.keys(a).sort();let s=function(){let e=new Set;for(let t of[void 0!==r&&r.env?r.env.PIGEON_FLAGS:void 0,r.env.NEXT_PUBLIC_PIGEON_FLAGS])if(t)for(let o of t.split(",")){let t=o.trim();if(t){if(!Object.prototype.hasOwnProperty.call(a,t)){console.warn('flags: ignoring unknown flag "'.concat(t,'" in PIGEON_FLAGS/NEXT_PUBLIC_PIGEON_FLAGS'));continue}e.add(t)}}return e}();function i(e){return!!s.has(e)||!0===a[e].value}}}]);